  role = excluded.role, department = excluded.department,
  bio = excluded.bio, social = excluded.social, display_order = excluded.display_order;

-- ── alumni ─────────────────────────────────────────────────────────────────
on conflict (full_name, tenure) do update set
  role = excluded.role, quote = excluded.quote, display_order = excluded.display_order;

-- ── events ─────────────────────────────────────────────────────────────────
on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle,
  description = excluded.description, event_type = excluded.event_type,
  event_date = excluded.event_date, venue = excluded.venue,
  display_order = excluded.display_order;

-- ── settings ───────────────────────────────────────────────────────────────
on conflict (key) do update set value = excluded.value, description = excluded.description;
